from the top-left corner.","requireAuth":true,"props":{"file":{"displayName":"PDF File or URL","required":true,"type":"FILE"},"textItems":{"displayName":"Text Items to Insert","description":"Add each piece of text you want to stamp.","required":true,"properties":{"text":{"displayName":"Text","required":true,"type":"LONG_TEXT"},"applyToAllPages":{"displayName":"Apply to all pages?","description":"If checked, this text is stamped on every page.","required":false,"defaultValue":false,"type":"CHECKBOX"},"pageNumber":{"displayName":"Page Number","description":"Which page to stamp? (Leave blank or ignore if applying to all pages)","required":false,"defaultValue":1,"type":"NUMBER"},"distanceFromLeft":{"displayName":"Distance from Left Edge (in pixels)","description":"0 is the far left edge of the page. Standard A4 width is about 595 pts.","required":true,"type":"NUMBER"},"distanceFromTop":{"displayName":"Distance from Top Edge (in pixels)","description":"0 is the very top edge of the page. Standard A4 height is about 842 pts.","required":true,"type":"NUMBER"},"font":{"displayName":"Font","description":"Select the exact font variant for this text item.","required":true,"defaultValue":"Helvetica","options":{"options":[{"label":"Courier","value":"Courier"},{"label":"Courier Bold","value":"Courier-Bold"},{"label":"Courier Oblique","value":"Courier-Oblique"},{"label":"Courier Bold Oblique","value":"Courier-BoldOblique"},{"label":"Helvetica","value":"Helvetica"},{"label":"Helvetica Bold","value":"Helvetica-Bold"},{"label":"Helvetica Oblique","value":"Helvetica-Oblique"},{"label":"Helvetica Bold Oblique","value":"Helvetica-BoldOblique"},{"label":"Times Roman","value":"Times-Roman"},{"label":"Times Roman Bold","value":"Times-Bold"},{"label":"Times Roman Italic","value":"Times-Italic"},{"label":"Times Roman Bold Italic","value":"Times-BoldItalic"},{"label":"Symbol","value":"Symbol"},{"label":"Zapf Dingbats","value":"ZapfDingbats"}]},"type":"STATIC_DROPDOWN"},"fontSize":{"displayName":"Font Size","required":true,"defaultValue":11,"type":"NUMBER"},"lineSpacing":{"displayName":"Line Spacing","description":"The vertical spacing multiplier between lines. (Examples: 1.0 = Single, 1.15 = Standard, 2.0 = Double)","required":false,"defaultValue":1.15,"type":"NUMBER"}},"type":"ARRAY"}},"errorHandlingOptions":{"retryOnFailure":{"hide":true},"continueOnFailure":{"defaultValue":false}}},"addImageToPdf":{"name":"addImageToPdf","displayName":"Add Image to PDF","description":"Stamps one or more images (PNG or JPG) at exact pixel distances from the top-left corner.","requireAuth":true,"props":{"file":{"displayName":"PDF File or URL","required":true,"type":"FILE"},"imageItems":{"displayName":"Image Items to Insert","description":"Add each image you want to stamp.","required":true,"properties":{"imageFile":{"displayName":"Image File (PNG/JPG)","description":"The signature or image file to insert.","required":true,"type":"FILE"},"applyToAllPages":{"displayName":"Apply to all pages?","description":"If checked, this image is stamped on every page.","required":false,"defaultValue":false,"type":"CHECKBOX"},"pageNumber":{"displayName":"Page Number","description":"Which page to stamp? (Leave blank or ignore if applying to all pages)","required":false,"defaultValue":1,"type":"NUMBER"},"distanceFromLeft":{"displayName":"Distance from Left Edge (in pixels)","description":"0 is the far left edge of the page. Standard A4 width is about 595 pts.","required":true,"type":"NUMBER"},"distanceFromTop":{"displayName":"Distance from Top Edge (in pixels)","description":"0 is the very top edge of the page. Standard A4 height is about 842 pts.","required":true,"type":"NUMBER"},"scale":{"displayName":"Image Scale","description":"Scale multiplier for the image (e.g., 0.5 for half size, 1.0 for original size).","required":true,"defaultValue":1,"type":"NUMBER"}},"type":"ARRAY"}},"errorHandlingOptions":{"retryOnFailure":{"hide":true},"continueOnFailure":{"defaultValue":false}}}}$ap$,
